body.query:
query($ids:[String!]!){
 entries(entry_ids:$ids){
  rcsb_id
  struct{title}
  exptl{method}
  rcsb_entry_info{resolution_combined polymer_entity_count_protein polymer_entity_count_nucleic_acid}
  rcsb_accession_info{initial_release_date}
  rcsb_primary_citation{title year pdbx_database_id_DOI pdbx_database_id_PubMed journal_abbrev}
  polymer_entities{
    rcsb_polymer_entity{pdbx_description}
    entity_poly{rcsb_entity_polymer_type}
    rcsb_entity_source_organism{ncbi_scientific_name ncbi_taxonomy_id}
    rcsb_polymer_entity_container_identifiers{reference_sequence_identifiers{database_name database_accession}}
  }
  nonpolymer_entities{pdbx_entity_nonpoly{comp_id name}}
 }}
